SELECT COUNT(*) FROM node_info
AND status = #{status}
AND (name LIKE '%' || #{keyword} || '%' OR ip LIKE '%' || #{keyword} || '%' OR tags LIKE '%' || #{keyword} || '%')

SELECT *, disk_info AS diskInfoJson, host_cpu_percent AS hostCpuPercent, host_memory_percent AS hostMemoryPercent, host_disk_percent AS diskUsagePercent FROM node_info
AND tenant_id = #{tenantId}
AND id IN (SELECT DISTINCT n.id FROM node_info n JOIN project_info p ON FIND_IN_SET(CAST(n.id AS VARCHAR), p.node_ids) > 0 WHERE p.tenant_id = #{tenantId} AND p.id IN #{projectId})
AND status = #{status}
AND (name LIKE '%' || #{keyword} || '%' OR ip LIKE '%' || #{keyword} || '%' OR tags LIKE '%' || #{keyword} || '%')
ORDER BY create_time DESC LIMIT #{pageSize} OFFSET (#{page} - 1) * #{pageSize}

SELECT COUNT(*) FROM node_info
AND tenant_id = #{tenantId}
AND id IN (SELECT DISTINCT n.id FROM node_info n JOIN project_info p ON FIND_IN_SET(CAST(n.id AS VARCHAR), p.node_ids) > 0 WHERE p.tenant_id = #{tenantId} AND p.id IN #{projectId})
AND status = #{status}
AND (name LIKE '%' || #{keyword} || '%' OR ip LIKE '%' || #{keyword} || '%' OR tags LIKE '%' || #{keyword} || '%')

mapper.update:
UPDATE node_info SET name = #{name}, tenant_id = #{tenantId}, ip = #{ip}, port = #{port}, token = #{token},
status = #{status}, os_info = #{osInfo}, java_version = #{javaVersion},
last_heartbeat = #{lastHeartbeat}, update_time = #{updateTime},
tags = #{tags}, cpu_cores = #{cpuCores}, total_memory_mb = #{totalMemoryMb},
total_disk_mb = #{totalDiskMb}, os_arch = #{osArch}
WHERE id = #{id}
